function Assert-O3B8([bool]$Condition,[string]$Message){if(-not$Condition){throw $Message}}
function Get-O3B8Sha([string]$Path){return(Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash}
$project=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..\..'));$zip=Join-Path $PSScriptRoot 'final\REQ_O3B8_20260828A.ready.zip';$expectedZip='BED3E048D6AFF6330A68A7EF3493353E9F954DD737BFEA5925331D63E25CE327';$root='C:\B8E';$successOut='C:\B8S';$failureOut='C:\B8F';$gatePath=Join-Path $PSScriptRoot 'O3B8_EXACT_PACKAGE_REHEARSAL_GATE.json'
