$utf8=New-Object Text.UTF8Encoding($false);$successManifest=Join-Path $root 'success.json';[IO.File]::WriteAllText($successManifest,((New-O3B8Invocation $successOut $bfTime.ToString('o'))|ConvertTo-Json -Depth 12),$utf8);$success=& $endpoint -Rehearsal -InvocationManifest $successManifest|ConvertFrom-Json
